SELECT 'ea1cd72d-e95a-577b-a888-0b08551bbecc', 'Cánh Đồng Bất Tận', NULL, 'Cánh Đồng Bất Tận (Phiên bản màu có minh họa) Nhà xuất bản : NXB Trẻ. Công ty phát hành : NXB Trẻ. Tác giả : Nguyễn Ngọc Tư. Kích thước : 19 x 24 cm. Số trang : 144. Ngày xuất bản : . Loại bìa : Bìa cứng. Cánh Đồng Bất Tận gồm hai truyện vừa là "Cánh đồng bất tận" và "Đất", là câu chuyện về những mảnh đời mải mốt bên dòng Mê Kông, đánh dấu sự thấu hiểu và cảm thông sâu sắc của Nguyễn Ngọc Tư với người nông dân (và con người nói chung). Bàng bạc khắp truyện là tình yêu thương, sự thù hận, nỗi nhớ nhung, niềm ân hận, và sự bóc trần những góc khuất tăm tối trong tâm hồn khiến cho nhân vật trong đó trở nên “đời” hơn bao giờ hết. Truyện vừa “Cánh đồng bất tận”, được chuyển thể thành phim năm 2010 với tên gọi “The Floating Lives”, đã được dịch và xuất bản ở Hàn Quốc, Trung Quốc, Pháp, Đức, Thụy Điển, và nhận được nhiều lời khen ngợi. “Kết cấu chặt chẽ và hoàn hảo… Nhiều hình ảnh gợi buồn về nỗi con người bị số phận hay chính cơ hội quật ngã.” - Nhà phê bình Thụy Điển Stefan Jonsson', (SELECT id FROM publishers WHERE name = NULL), NULL, NULL, 'vi', true, '{"source":"catalog-expansion","lookup_sources":["tiki"]}'::jsonb
