SELECT 'c77943f6-1433-5b95-8b47-3ff41f6bbe5a', 'Truyện Kiều', NULL, 'Truyện Kiều Tác phẩm Truyện Kiều , nguyên tên là Đoạn trường tân thanh, từ khi ra đời đến nay (khoảng 200 năm), trong lịch sử Văn học Việt Nam chưa có công trình nào nghiên cứu sâu sắc về nó. Một trong nguyên nhân chính là vì bản gốc của Nguyễn Du sáng tác không còn nữa. Tuy nhiên, không phải vì vậy mà Truyện Kiều bị mai một. Truyện Kiều vẫn trường tồn với thời gian, những lời thơ, câu chữ đến nay vẫn còn nguyên giá trị: "Trăm năm trong cõi người ta, Chữ tài chữ mệnh khéo là ghét nhau. Trải qua một cuộc bể dâu, Những điều trông thấy mà đau đớn lòng. Lạ gì bỉ sắc tư phong, Trời xanh quen thói má hồng đánh ghen".', (SELECT id FROM publishers WHERE name = 'Nhà Xuất Bản Văn Học'), '2015-01-01', 176, 'vi', true, '{"source":"catalog-expansion","lookup_sources":["fahasa","tiki"],"source_url":"https://www.fahasa.com/truyen-kieu-124442.html"}'::jsonb
