UPDATE books SET description = '“- Tôi không muốn lấy cái người ấy, vì nếu tôi lấy hắn, chắc hắn sẽ mọc sừng. Thí dụ một người như ông mà hỏi tôi thì còn nói gì! Đằng này hắn lại nhà quê, không biết yêu vợ như những người văn minh. Buồn lắm anh ạ. - Tôi phải làm gì? - Phải giả vờ chim tô, chúng ta giả vờ chim nhau, mê Cho hắn bỏ tôi, mình hiểu chưa? Ta giả vờ với nhau thôi mà! Tôi cần mang tiếng hư hỏng lắm mới được. - Thế sao nữa ạ? - Anh thì anh cũng phải mang tiếng là làm hại một đời tôi mới xong!”', updated_at = now() WHERE id = 'ff5ec777-a2b8-5b6c-9879-3c6552bc6c87' AND metadata->>'source' = 'catalog-expansion' AND description IS DISTINCT FROM '“- Tôi không muốn lấy cái người ấy, vì nếu tôi lấy hắn, chắc hắn sẽ mọc sừng. Thí dụ một người như ông mà hỏi tôi thì còn nói gì! Đằng này hắn lại nhà quê, không biết yêu vợ như những người văn minh. Buồn lắm anh ạ. - Tôi phải làm gì? - Phải giả vờ chim tô, chúng ta giả vờ chim nhau, mê Cho hắn bỏ tôi, mình hiểu chưa? Ta giả vờ với nhau thôi mà! Tôi cần mang tiếng hư hỏng lắm mới được. - Thế sao nữa ạ? - Anh thì anh cũng phải mang tiếng là làm hại một đời tôi mới xong!”';
