SELECT 'c85a3110-08ce-50ef-b673-b7836e0d2eaa', 'Ông Già Và Biển Cả', NULL, 'Ernest Hemingway (1899 -1961) là một tiểu thuyết gia người Mỹ, một nhà văn viết truyện ngắn, và là một nhà báo. Ông từng tham gia chiến đấu trong Chiến tranh thế giới lần thứ I, sau đó ông được biết đến qua "Thế hệ đã mất", nhận được giải thưởng báo chí Pulitzer năm 1953 với tiểu thuyết Ông già và biển cả, và giải Nobel NXB Văn Học năm 1954. Hemingway để lại ấn tượng sâu sắc đối với bạn đọc qua nguyên lý “tảng băng trôi”, văn phong của ông được mô tả bởi sự kiệm lời nhưng có nhiều tầng ý nghĩa, phải suy nghĩ thật sâu mới có thể hiểu hết được những gì tác giả gửi gắm. Nhiều tác phẩm của ông hiện nay được coi là những tác phẩm kinh điển của nền NXB Văn Học Mỹ: Ông già và biển cả, Chuông nguyện hồn ai, Giã từ vũ khí, Hạnh phúc ngắn ngủi của Mác Cômbơ, Hội hè miên man,…', (SELECT id FROM publishers WHERE name = 'Nhà Xuất Bản Văn Học'), '2022-01-01', 148, 'vi', true, '{"source":"catalog-expansion","lookup_sources":["tiki"],"source_url":"https://tiki.vn/sach-ong-gia-va-bien-ca-p195545372.html?spid=195545373"}'::jsonb
