SELECT 'c582391c-cc4f-5efa-83ec-bfb2ddbd4502', 'Wuthering Heights', NULL, 'Wuthering Heights is an 1847 novel by Emily Brontë, initially published under the pseudonym Ellis Bell. It concerns two families of the landed gentry living on the West Yorkshire moors, the Earnshaws and the Lintons, and their turbulent relationships with Earnshaw''s adopted son, Heathcliff. The novel was influenced by Romanticism and Gothic fiction.', (SELECT id FROM publishers WHERE name = 'RAS Publishing'), '2021-01-01', 478, 'en', true, '{"source":"catalog-expansion","lookup_sources":["openLibrary"],"source_url":"https://openlibrary.org/isbn/9798542843742"}'::jsonb
