SELECT '062c9e98-b9a9-5716-ade0-3c320415442a', 'To Kill a Mockingbird', NULL, 'One of the best-loved stories of all time, To Kill a Mockingbird has been translated into more than forty languages, sold more than thirty million copies worldwide, served as the basis of an enormously popular motion picture, and was voted one of the best novels of the twentieth century by librarians across the country. A gripping, heart wrenching, and wholly remarkable tale of coming-of-age in a South poisoned by viruletn prejudice, it views a world of great beauty and savage inequities through the eyes of a youn girl, as her father--a crusading local lawyer--risks everything to defend a black man unjustly accused of a terrible crime. (front flap)', (SELECT id FROM publishers WHERE name = 'Harper Perennial Modern Classics'), '2006-01-01', 323, 'en', true, '{"source":"catalog-expansion","lookup_sources":["openLibrary"],"source_url":"https://openlibrary.org/isbn/9780061120084"}'::jsonb
