SELECT 'fa33ebc6-f95b-5f56-9c8a-5ec43860b0d4', 'The Pragmatic Programmer', 'From Journeyman to Master', 'The Pragmatic Programmer: From Journeyman to Master examines the core programming process: taking a requirement and producing working, maintainable code that delights its users. It covers topics ranging from personal responsibility and career development to architectural techniques for keeping code flexible, easy to adapt, and reuse. (publisher''s copy)', (SELECT id FROM publishers WHERE name = 'Addison-Wesley'), '1999-01-01', 352, 'en', true, '{"source":"catalog-expansion","lookup_sources":["openLibrary"],"source_url":"https://openlibrary.org/isbn/9780201616224"}'::jsonb
