SELECT '93f99f2a-c970-569e-9382-4d595be5ec5a', 'The Hobbit', NULL, 'The Hobbit is a tale of high adventure, undertaken by a company of dwarves in search of dragon-guarded gold. A reluctant partner in this perilous quest is Bilbo Baggins, a comfort-loving unambitious hobbit, who surprises even himself by his resourcefulness and skill as a burglar. Encounters with trolls, goblins, dwarves, elves, and giant spiders, conversations with the dragon, Smaug, and a rather unwilling presence at the Battle of Five Armies are just some of the adventures that befall Bilbo. Bilbo Baggins has taken his place among the ranks of the immortals of children’s fiction. Written by Professor Tolkien for his children, The Hobbit met with instant critical acclaim when published.', (SELECT id FROM publishers WHERE name = 'Klett'), '2001-01-01', 364, 'en', true, '{"source":"catalog-expansion","lookup_sources":["openLibrary"],"source_url":"https://openlibrary.org/isbn/9783125777705"}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM book_variants v WHERE v.sku = 'IMPORT-9783125777705' OR v.internal_barcode = '9783125777705' OR v.isbn13 = '9783125777705') AND NOT EXISTS (SELECT 1 FROM books WHERE id = '93f99f2a-c970-569e-9382-4d595be5ec5a');
SELECT '50a93486-20fb-5700-a980-c837df21241e', '93f99f2a-c970-569e-9382-4d595be5ec5a', 'IMPORT-9783125777705', '9783125777705', '9783125777705', 'PAPERBACK', 'en', 2001, 'NEW', 0, 0, 0, true, false, 'https://covers.openlibrary.org/b/id/996169-L.jpg', true
WHERE EXISTS (SELECT 1 FROM books WHERE id = '93f99f2a-c970-569e-9382-4d595be5ec5a') AND NOT EXISTS (SELECT 1 FROM book_variants v WHERE v.sku = 'IMPORT-9783125777705' OR v.internal_barcode = '9783125777705' OR v.isbn13 = '9783125777705');
